class Cache:
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock
        self.cache = {}

    def set(self, key, value):
        self.cache[key] = value
        self._refresh_expiry(key)

    def _refresh_expiry(self, key):
        if self.clock is None:
            return
        now = self.clock.now()
        if key in self.cache:
            key_expiry = self._get_expiry(key)
            if key_expiry is not None and now >= key_expiry:
                del self.cache[key]
        self.cache[key] = value
        self._set_expiry(key, self._get_expiry(key))

    def _get_expiry(self, key):
        if key not in self.cache:
            return None
        expiry = self._set_expiry(key)
        return expiry

    def _set_expiry(self, key, expiry):
        if expiry is None:
            return
        self.cache[key] = expiry

